window.docContents[194].resolve({"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Representations-of-quivers-as-representations-of-path-algebras/#Introduction-to-Representation-Theory--2___-Basic-notions-of-representation-theory--2___8___-Quivers--Representations-of-quivers-as-representations-of-path-algebras--Representations-of-quivers-as-representations-of-path-algebras--Formalization--Primary-declarations":{"contents":"There is an equivalence between quotient classes of encoded modules and representations, compatible with both constructions.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter2/Discussion_path_algebra_intro; role=primary]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter2/Discussion_quiver_rep_bijection; role=primary]\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.8. Quivers\u0009Representations of quivers as representations of path algebras\u0009Representations of quivers as representations of path algebras\u0009Formalization","header":"Primary declarations","id":"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Representations-of-quivers-as-representations-of-path-algebras/#Introduction-to-Representation-Theory--2___-Basic-notions-of-representation-theory--2___8___-Quivers--Representations-of-quivers-as-representations-of-path-algebras--Representations-of-quivers-as-representations-of-path-algebras--Formalization--Primary-declarations"},"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Lie-algebra/#Chapter2___Definition2___9___1":{"contents":"Definition 2.9.1. (\\mathfrak{g}, [\\ ,\\ ]) is a Lie algebra if [\\ ,\\ ] satisfies the Jacobi identity\n\n(2.9.1) \\qquad [[a, b], c] + [[b, c], a] + [[c, a], b] = 0.\n\n\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.9. Lie algebras\u0009Lie algebra","header":"Lie algebra","id":"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Lie-algebra/#Chapter2___Definition2___9___1"},"/3___-General-results-of-representation-theory/3___1___-Subrepresentations-in-semisimple-representations/Generalization-of-Proposition-3___1___4-to-non-algebraically-closed-fields/#Chapter3___Remark3___1___5":{"contents":"Remark 3.1.5. In Proposition 3.1.4, it is not important that k is algebraically closed, nor does it matter that V is finite dimensional. If these assumptions are dropped, the only change needed is that the entries of the matrix X_i are no longer in k but in D_i = \\operatorname{End}_A(V_i), which is, as we know, a division algebra. The proof of this generalized version of Proposition 3.1.4 is the same as before (check it!).\n\n\n\n","context":"Introduction to Representation Theory\u00093. General results of representation theory\u00093.1. Subrepresentations in semisimple representations\u0009Generalization of Proposition 3.1.4 to non-algebraically-closed fields","header":"Generalization of Proposition 3.1.4 to non-algebraically-closed fields","id":"/3___-General-results-of-representation-theory/3___1___-Subrepresentations-in-semisimple-representations/Generalization-of-Proposition-3___1___4-to-non-algebraically-closed-fields/#Chapter3___Remark3___1___5"},"/3___-General-results-of-representation-theory/3___6___-Characters-of-representations/Section-3___6___-Characters-of-representations-___-heading-and-character-definition/#Chapter3___Introduction_to_3___6___formalization":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\u00093. General results of representation theory\u00093.6. Characters of representations\u0009Section 3.6: Characters of representations — heading and character definition\u0009Section 3.6: Characters of representations — heading and character definition","header":"Formalization","id":"/3___-General-results-of-representation-theory/3___6___-Characters-of-representations/Section-3___6___-Characters-of-representations-___-heading-and-character-definition/#Chapter3___Introduction_to_3___6___formalization"},"/4___-Representations-of-finite-groups___-Basic-results/4___3___-Examples/Irreducible-representations-of-S_4/#Introduction-to-Representation-Theory--4___-Representations-of-finite-groups___-Basic-results--4___3___-Examples--Irreducible-representations-of-S_4--Irreducible-representations-of-S_4--Formalization--Primary-declarations":{"contents":"Every simple finite-dimensional complex representation of the specified group is isomorphic to one of the five listed auxiliary representations.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter4/Example4.3_S4; role=primary]\n\n","context":"Introduction to Representation Theory\u00094. Representations of finite groups: Basic results\u00094.3. Examples\u0009Irreducible representations of S_4\u0009Irreducible representations of S_4\u0009Formalization","header":"Primary declarations","id":"/4___-Representations-of-finite-groups___-Basic-results/4___3___-Examples/Irreducible-representations-of-S_4/#Introduction-to-Representation-Theory--4___-Representations-of-finite-groups___-Basic-results--4___3___-Examples--Irreducible-representations-of-S_4--Irreducible-representations-of-S_4--Formalization--Primary-declarations"},"/5___-Representations-of-finite-groups___-Further-results/5___18___-Schur-Weyl-duality-for-______mathfrak___gl____LPAR_V_RPAR____/Section-5___18___-Schur-Weyl-duality-for-gl_LPAR_V_RPAR_-___-Double-Centralizer-Theorem/#Chapter5___Introduction_5___18___heading-1":{"contents":"We start with a simple result which is called the Double Centralizer Theorem.\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.18. Schur-Weyl duality for $\\mathfrak{gl}(V)$\u0009Section 5.18: Schur-Weyl duality for gl(V) — Double Centralizer Theorem\u0009Section 5.18: Schur-Weyl duality for gl(V) — Double Centralizer Theorem","header":"5.18. Schur-Weyl duality for  \\mathfrak{gl}(V)","id":"/5___-Representations-of-finite-groups___-Further-results/5___18___-Schur-Weyl-duality-for-______mathfrak___gl____LPAR_V_RPAR____/Section-5___18___-Schur-Weyl-duality-for-gl_LPAR_V_RPAR_-___-Double-Centralizer-Theorem/#Chapter5___Introduction_5___18___heading-1"},"/7___-Introduction-to-categories/7___2___-Functors/Functor/#Chapter7___Definition7___2___1":{"contents":"Definition 7.2.1. A functor F : \\mathcal{C} \\to \\mathcal{D} between categories \\mathcal{C} and \\mathcal{D} is\n\n(i) a map F : Ob(\\mathcal{C}) \\to Ob(\\mathcal{D});\n(ii) for each X, Y \\in \\mathcal{C}, a map F = F_{X,Y} : \\operatorname{Hom}(X, Y) \\to \\operatorname{Hom}(F(X), F(Y)) which preserves compositions and identity morphisms.\n\n\n\n","context":"Introduction to Representation Theory\u00097. Introduction to categories\u00097.2. Functors\u0009Functor","header":"Functor","id":"/7___-Introduction-to-categories/7___2___-Functors/Functor/#Chapter7___Definition7___2___1"},"/7___-Introduction-to-categories/7___9___-Exact-functors/Additive-functors-preserve-direct-sums/#Chapter7___Discussion_after_Definition7___9___1___formalization":{"contents":"\n\n","context":"Introduction to Representation Theory\u00097. Introduction to categories\u00097.9. Exact functors\u0009Additive functors preserve direct sums\u0009Additive functors preserve direct sums","header":"Formalization","id":"/7___-Introduction-to-categories/7___9___-Exact-functors/Additive-functors-preserve-direct-sums/#Chapter7___Discussion_after_Definition7___9___1___formalization"},"/9___-Structure-of-finite-dimensional-algebras/9___6___-Finite-abelian-categories/Finite-abelian-categories-are-module-categories/#Introduction-to-Representation-Theory--9___-Structure-of-finite-dimensional-algebras--9___6___-Finite-abelian-categories--Finite-abelian-categories-are-module-categories--Finite-abelian-categories-are-module-categories--Formalization--Primary-declarations":{"contents":"Under the displayed field-linear hypotheses, the module functor is an equivalence.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter9/Theorem9.6.4; role=primary]\n\nThe module functor is an equivalence when the opposite endomorphism ring is noetherian.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter9/Theorem9.6.4; role=primary]\n\nUnder the displayed field-linear hypotheses, an equivalence with finitely generated modules\nover the opposite endomorphism ring exists.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter9/Theorem9.6.4; role=primary]\n\nA noetherian opposite endomorphism ring gives an equivalence with its finitely generated\nmodules.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter9/Theorem9.6.4; role=primary]\n\n","context":"Introduction to Representation Theory\u00099. Structure of finite dimensional algebras\u00099.6. Finite abelian categories\u0009Finite abelian categories are module categories\u0009Finite abelian categories are module categories\u0009Formalization","header":"Primary declarations","id":"/9___-Structure-of-finite-dimensional-algebras/9___6___-Finite-abelian-categories/Finite-abelian-categories-are-module-categories/#Introduction-to-Representation-Theory--9___-Structure-of-finite-dimensional-algebras--9___6___-Finite-abelian-categories--Finite-abelian-categories-are-module-categories--Finite-abelian-categories-are-module-categories--Formalization--Primary-declarations"}});